from itertools import combinations
import numpy as np
from scipy.optimize import linprog

def solve_for_S(N, s, S):
    num_tiles = (N - s + 1) ** 2
    A = []
    b = []
    for (i, j) in S:
        row = [0] * num_tiles
        for r in range(max(0, i - s + 1), min(i + 1, N - s + 1)):
            for c in range(max(0, j - s + 1), min(j + 1, N - s + 1)):
                row[r * (N - s + 1) + c] = 1
        A.append(row)
        b.append(1)
    res = linprog(np.zeros(num_tiles), A_eq=A, b_eq=b, bounds=(0, None), method='highs')
    return res.success

def brute_force_k(N, s):
    cells = [(i, j) for i in range(N) for j in range(N)]
    for k in range(N * N, 0, -1):
        for S in combinations(cells, k):
            if solve_for_S(N, s, S):
                return k
    return 0

print(f"N=4, s=3: {brute_force_k(4, 3)}")

